phase7_js = r'''
/* ---------- Phase 7 integrations and data portability ---------- */
const DATA_TABS=[['exports','⇩','Export Center'],['vtt','◫','VTT Formats'],['errata','!','Errata & Overlays'],['backup','⎘','Backup & Import'],['updates','∆','Update Comparison']];
const EXPORT_FORMATS={json:'Normalized JSON',csv:'CSV table',markdown:'Markdown bundle',foundry:'Foundry portable JSON',roll20:'Roll20 handout JSON'};
function cleanSerializable(value){return JSON.parse(JSON.stringify(value,(key,item)=>key.startsWith('_')?undefined:item));}
function fnv1a(value){let hash=0x811c9dc5;const text=typeof value==='string'?value:JSON.stringify(value);for(let i=0;i<text.length;i++){hash^=text.charCodeAt(i);hash=Math.imul(hash,0x01000193);}return (hash>>>0).toString(16).padStart(8,'0');}
function canonicalRecordHash(record){return fnv1a(cleanSerializable(record));}
function downloadText(text,filename,type='text/plain'){const blob=new Blob([text],{type});const anchor=document.createElement('a');anchor.href=URL.createObjectURL(blob);anchor.download=filename;anchor.click();setTimeout(()=>URL.revokeObjectURL(anchor.href),1000);}
function csvCell(value){const text=Array.isArray(value)?value.join('|'):String(value??'');return /[",\n]/.test(text)?'"'+text.replace(/"/g,'""')+'"':text;}
function recordsCSV(records){const cols=['id','name','type','category','subtype','book','chapter','section','level','role','encounterValue','actionType','cost','keywords','summary','body'];const rows=[cols.join(',')];for(const r of records)rows.push([r.id,r.name,r.type,r.category,r.subtype,r.source?.book,r.source?.chapter,r.source?.section,r.level,r.role,r.encounterValue,r.actionType,r.cost,r.keywords,r.summary,plainText(r.body)].map(csvCell).join(','));return rows.join('\n');}
function recordMarkdown(record){const meta=[`**Type:** ${label(record)}`,sourceText(record)?`**Source:** ${sourceText(record)}`:'',record.level!==null?`**Level:** ${record.level}`:'',record.role?`**Role:** ${record.role}`:'',record.encounterValue!==null?`**EV:** ${record.encounterValue}`:'',record.actionType?`**Action:** ${record.actionType}`:'',record.cost?`**Cost:** ${record.cost}`:''].filter(Boolean).join('  \n');return `# ${record.name}\n\n${meta}\n\n${record.body||record.summary||''}\n\n---\nStable ID: \`${record.id}\`\n`;}
function recordsMarkdown(records){return records.map(recordMarkdown).join('\n\n');}
function foundryDocument(record){const description=window.marked?marked.parse(record.body||record.summary||''):esc(record.body||record.summary||'');const base={name:record.name,type:record.type==='monster'?'npc':'item',img:'icons/svg/book.svg',system:{description:{value:description},source:sourceText(record),level:effectiveValue(record,'level'),role:effectiveValue(record,'role'),encounterValue:effectiveValue(record,'encounterValue'),actionType:record.actionType,cost:record.cost,keywords:record.keywords||[]},flags:{drawSteelCompendium:{recordId:record.id,recordType:record.type,normalizationStatus:record.normalizationStatus,portableSchema:'v1'}}};if(record.type==='monster')base.img='icons/svg/mystery-man.svg';return base;}
function foundryPackage(records){return {schema:'draw-steel-foundry-portable-v1',exportedAt:new Date().toISOString(),notice:'Generic portable documents. A Foundry Draw Steel system or importer must map these fields to its installed system schema.',actors:records.filter(r=>r.type==='monster').map(foundryDocument),items:records.filter(r=>r.type!=='monster').map(foundryDocument)};}
function roll20Package(records){return {schema:'draw-steel-roll20-handouts-v1',exportedAt:new Date().toISOString(),notice:'Portable handout data; Roll20 campaign import capabilities vary. Use a compatible API script or copy handout fields manually.',handouts:records.map(record=>({name:record.name,notes:window.marked?marked.parse(record.body||record.summary||''):record.body||record.summary||'',gmnotes:`Stable ID: ${record.id}\nType: ${record.type}\nSource: ${sourceText(record)}`,tags:[record.type,record.category,...(record.keywords||[])].filter(Boolean)}))};}
function normalizedPackage(records,name='Draw Steel records'){const cleaned=records.map(cleanSerializable);return {schema:'draw-steel-normalized-package-v1',manifest:{name,exportedAt:new Date().toISOString(),recordCount:cleaned.length,sourceApplication:'Draw Steel Compendium Phase 7',checksum:fnv1a(cleaned)},records:cleaned};}
function currentExportRecords(){let records=[];switch(state.exportSource){case'current':records=CURRENT_RESULT_IDS.map(id=>RECORD_BY_ID.get(id)).filter(Boolean);break;case'pinned':records=[...state.pinned].map(id=>RECORD_BY_ID.get(id)).filter(Boolean);break;case'favorites':records=[...state.favorites].map(id=>RECORD_BY_ID.get(id)).filter(Boolean);break;case'hero':records=selectedHeroRecords();break;case'collection':records=(collectionById(state.activeCollectionId)?.recordIds||[]).map(id=>RECORD_BY_ID.get(id)).filter(Boolean);break;case'encounter':records=(activeEncounter()?.items||[]).map(item=>RECORD_BY_ID.get(item.monsterId)).filter(Boolean);break;case'type':records=state.exportType==='all'?RECORDS:(RECORDS_BY_TYPE.get(state.exportType)||[]);break;case'category':records=state.exportCategory==='all'?RECORDS:RECORDS.filter(r=>r.category===state.exportCategory);break;default:records=RECORDS;}return [...new Map(records.map(r=>[r.id,r])).values()].sort((a,b)=>a.name.localeCompare(b.name));}
function runExport(records,format=state.exportFormat,basename='draw-steel-export'){if(!records.length)return;const safe=slugPart(basename);if(format==='csv')downloadText(recordsCSV(records),safe+'.csv','text/csv');else if(format==='markdown')downloadText(recordsMarkdown(records),safe+'.md','text/markdown');else if(format==='foundry')downloadObject(foundryPackage(records),safe+'-foundry.json');else if(format==='roll20')downloadObject(roll20Package(records),safe+'-roll20.json');else downloadObject(normalizedPackage(records,basename),safe+'.json');}
function setRecordDragData(event,record){if(!event.dataTransfer||!record)return;const payload={schema:'draw-steel-record-drag-v1',record:cleanSerializable(record)};event.dataTransfer.effectAllowed='copy';event.dataTransfer.setData('application/x-draw-steel-record+json',JSON.stringify(payload));event.dataTransfer.setData('application/json',JSON.stringify(payload));event.dataTransfer.setData('text/plain',recordMarkdown(record));event.target?.classList.add('drag-ready');setTimeout(()=>event.target?.classList.remove('drag-ready'),500);}
document.addEventListener('dragstart',event=>{const node=event.target.closest?.('[data-id],[data-drag-record]');const id=node?.dataset.id||node?.dataset.dragRecord;if(id&&RECORD_BY_ID.has(id))setRecordDragData(event,RECORD_BY_ID.get(id));});
function recordOverlayHTML(record){const errata=errataForRecord(record.id),overlays=overlaysForRecord(record.id);let html='';if(errata.length)html+=`<section class="errata-overlay"><h3>Errata and annotations (${errata.length})</h3>${errata.map(item=>`<article class="errata-entry"><strong>${esc(item.title)} <span class="provenance-status">${esc(item.status)}</span></strong><p>${esc(item.text)}</p><div class="errata-source">${esc([item.source,item.effectiveDate].filter(Boolean).join(' · '))}${item.sourceUrl?` · <a href="${esc(item.sourceUrl)}" target="_blank" rel="noopener">Source link</a>`:''}</div></article>`).join('')}</section>`;if(overlays.length){const aliases=[...new Set(overlays.flatMap(item=>item.patch.aliases||[]))],tags=[...new Set(overlays.flatMap(item=>item.patch.tags||[]))],notes=overlays.map(item=>item.patch.note).filter(Boolean);html+=`<section class="overlay-note"><h3>Imported overlay metadata</h3>${aliases.length?`<div><strong>Aliases:</strong> ${esc(aliases.join(', '))}</div>`:''}${tags.length?`<div class="overlay-badges">${tags.map(tag=>`<span class="overlay-badge">${esc(tag)}</span>`).join('')}</div>`:''}${notes.map(note=>`<p>${esc(note)}</p>`).join('')}<div class="errata-source">${esc([...new Set(overlays.map(item=>item.pack.manifest.name))].join(', '))}</div></section>`;}return html;}
function openDataTools(tab='exports',push=true){state.view='data';state.dataTab=DATA_TABS.some(item=>item[0]===tab)?tab:'exports';state.selectedId=null;state.section='';closeDrawer();render();setHash(push);}
function exportSourceOptions(){return [['all','All normalized records'],['current','Current browser result list'],['pinned','Pinned records'],['favorites','Favorite records'],['hero','Active hero reference'],['collection','Active session collection'],['encounter','Active encounter monsters'],['type','One record type'],['category','One category']];}
function exportCenterHTML(){const records=currentExportRecords(),types=[...RECORDS_BY_TYPE.keys()].sort(),categories=[...new Set(RECORDS.map(r=>r.category))].sort();return `<div class="data-grid"><section class="data-panel"><header class="data-panel-head"><div><h3>Structured export</h3><p>Export authoritative normalized records without private workspace data.</p></div><span>${records.length.toLocaleString()} records</span></header><div class="data-panel-body"><div class="data-form"><div class="data-field"><label>Record source</label><select id="exportSource">${exportSourceOptions().map(([value,name])=>`<option value="${value}" ${state.exportSource===value?'selected':''}>${esc(name)}</option>`).join('')}</select></div><div class="data-field"><label>Format</label><select id="exportFormat">${Object.entries(EXPORT_FORMATS).map(([value,name])=>`<option value="${value}" ${state.exportFormat===value?'selected':''}>${esc(name)}</option>`).join('')}</select></div>${state.exportSource==='type'?`<div class="data-field full"><label>Record type</label><select id="exportType"><option value="all">All types</option>${types.map(type=>`<option value="${esc(type)}" ${state.exportType===type?'selected':''}>${esc(label({type}))}</option>`).join('')}</select></div>`:''}${state.exportSource==='category'?`<div class="data-field full"><label>Category</label><select id="exportCategory"><option value="all">All categories</option>${categories.map(category=>`<option value="${esc(category)}" ${state.exportCategory===category?'selected':''}>${esc(category)}</option>`).join('')}</select></div>`:''}</div><div class="data-actions"><button class="data-btn primary" id="runExport" ${records.length?'':'disabled'}>Export ${records.length.toLocaleString()} records</button><button class="data-btn" id="exportManifest">Manifest only</button></div><div class="data-note">Internal search fields beginning with an underscore are excluded. User profiles, collections, encounters, pins, and learning progress are exported separately through Backup & Import.</div><div class="export-preview">${records.slice(0,80).map(record=>`<div class="export-row"><strong>${esc(record.name)}</strong><span>${esc(label(record))}</span><span>${esc(sourceText(record))}</span></div>`).join('')}${records.length>80?`<div class="export-row"><strong>…and ${(records.length-80).toLocaleString()} more</strong><span></span><span></span></div>`:''}</div></div></section><aside><section class="data-panel"><header class="data-panel-head"><div><h3>Package integrity</h3><p>Deterministic checksums support update comparison.</p></div></header><div class="data-panel-body"><div class="data-stats"><div class="data-stat"><strong>${records.length.toLocaleString()}</strong><span>Records</span></div><div class="data-stat"><strong>${new Set(records.map(r=>r.type)).size}</strong><span>Types</span></div><div class="data-stat"><strong>${fnv1a(records.map(cleanSerializable))}</strong><span>Checksum</span></div></div></div></section>${schemaCardsHTML()}</aside></div>`;}
function schemaCardsHTML(){return `<section class="data-panel"><header class="data-panel-head"><div><h3>Supported schemas</h3><p>Versioned envelopes make imports predictable.</p></div></header><div class="data-panel-body"><div class="schema-card"><h4>Normalized records</h4><p>Complete source-derived records with stable IDs.</p><code class="schema-code">draw-steel-normalized-package-v1</code></div><div class="schema-card"><h4>Workspace backup</h4><p>Private local profiles, collections, encounters, preferences, and overlays.</p><code class="schema-code">draw-steel-workspace-backup-v1</code></div><div class="schema-card"><h4>Overlay pack</h4><p>Non-destructive aliases, tags, and annotations keyed to stable IDs.</p><code class="schema-code">draw-steel-overlay-pack-v1</code></div></div></section>`;}
function vttHTML(){const records=currentExportRecords().slice(0,5000),sample=records[0]||RECORDS[0];return `<section class="data-panel"><header class="data-panel-head"><div><h3>VTT portability</h3><p>Generic, documented packages intended for mapping by a compatible importer or system module.</p></div><span>${records.length.toLocaleString()} source records</span></header><div class="data-panel-body"><div class="portability-grid"><article class="portability-card"><h4>Foundry portable documents</h4><p>Monsters become generic Actor documents; other game elements become generic Item documents with Draw Steel flags.</p><span class="format-badge">JSON</span><span class="format-badge">Actor</span><span class="format-badge">Item</span><div class="data-actions"><button class="data-btn primary" id="exportFoundry">Export current source</button></div></article><article class="portability-card"><h4>Roll20 handout package</h4><p>Rules text becomes handout notes with stable IDs and source information in GM notes.</p><span class="format-badge">JSON</span><span class="format-badge">Handouts</span><div class="data-actions"><button class="data-btn primary" id="exportRoll20">Export current source</button></div></article><article class="portability-card"><h4>Clipboard and drag payload</h4><p>Every result and record can be dragged as custom JSON, standard JSON, or Markdown text.</p><span class="format-badge">Drag</span><span class="format-badge">Clipboard</span><div class="data-actions"><button class="data-btn" id="copyVttSample">Copy sample payload</button></div></article></div><div class="data-note data-warning">These are portable interchange formats, not promises of direct one-click import into every VTT. Installed Draw Steel systems may use different field names and document types.</div><div class="data-field full"><label>Sample payload: ${esc(sample.name)}</label><textarea class="clipboard-output" id="vttSample" readonly>${esc(JSON.stringify({schema:'draw-steel-record-drag-v1',record:cleanSerializable(sample)},null,2))}</textarea></div></div></section>`;}
function errataHTML(){const filter=state.errataFilterRecordId,items=state.errataOverlays.filter(item=>!filter||item.recordId===filter),record=filter&&RECORD_BY_ID.get(filter);return `<div class="data-grid"><section class="data-panel"><header class="data-panel-head"><div><h3>${record?`Annotations for ${esc(record.name)}`:'Errata and annotations'}</h3><p>Overlays remain separate from source-derived rules text and always display provenance.</p></div><button class="data-btn" id="clearErrataFilter" ${filter?'':'disabled'}>Show all</button></header><div class="data-panel-body"><div class="data-form"><div class="data-field full"><label>Record</label><input id="errataRecord" list="recordIdOptions" value="${esc(filter||'')}" placeholder="Stable ID or exact record name"><datalist id="recordIdOptions">${RECORDS.slice(0,3000).map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')}</datalist></div><div class="data-field"><label>Status</label><select id="errataStatus"><option value="official">Official errata</option><option value="community">Community clarification</option><option value="personal" selected>Personal annotation</option></select></div><div class="data-field"><label>Effective date</label><input id="errataDate" type="date"></div><div class="data-field full"><label>Title</label><input id="errataTitle" placeholder="Correction, clarification, or table ruling"></div><div class="data-field full"><label>Annotation</label><textarea id="errataText" placeholder="State exactly what changed or how this note should be interpreted."></textarea></div><div class="data-field"><label>Source label</label><input id="errataSource" placeholder="MCDM FAQ, Discord ruling, campaign note…"></div><div class="data-field"><label>Source URL</label><input id="errataUrl" placeholder="https://…"></div></div><div class="data-actions"><button class="data-btn primary" id="addErrata">Add annotation</button><button class="data-btn" id="exportErrata">Export errata pack</button><label class="data-btn">Import errata pack<input id="importErrata" type="file" accept="application/json,.json" hidden></label></div><div class="data-note">“Official” is a user-supplied classification. The application does not verify that status automatically; include a source label and URL for auditability.</div>${items.map(item=>{const target=RECORD_BY_ID.get(item.recordId);return `<article class="errata-card ${esc(item.status)}"><div class="errata-card-head"><div><h4>${esc(item.title)}</h4><div class="errata-meta"><button class="errata-record-link" data-open-errata-record="${esc(item.recordId)}">${esc(target?.name||item.recordId)}</button> · ${esc(item.status)}${item.effectiveDate?' · '+esc(item.effectiveDate):''}</div></div><button class="data-btn danger" data-delete-errata="${esc(item.id)}">Delete</button></div><p>${esc(item.text)}</p><div class="errata-meta">${esc(item.source)}${item.sourceUrl?` · <a href="${esc(item.sourceUrl)}" target="_blank" rel="noopener">Source link</a>`:''}</div></article>`}).join('')||'<div class="notice">No annotations match this view.</div>'}</div></section><aside>${overlayPackPanelHTML()}</aside></div>`;}
function overlayPackPanelHTML(){return `<section class="data-panel"><header class="data-panel-head"><div><h3>Overlay packs</h3><p>Aliases, tags, and notes keyed to stable record IDs.</p></div><span>${state.overlayPacks.length}</span></header><div class="data-panel-body">${state.overlayPacks.map(pack=>`<article class="schema-card"><h4>${esc(pack.manifest.name)} ${esc(pack.manifest.version)}</h4><p>${pack.patches.length} valid patches · ${esc(pack.manifest.source||'No source')}</p><div class="data-actions"><button class="data-btn danger" data-delete-overlay="${esc(pack.id)}">Remove</button></div></article>`).join('')||'<div class="notice">No overlay packs imported.</div>'}<div class="data-actions"><button class="data-btn" id="downloadOverlayTemplate">Download template</button><label class="data-btn primary">Import overlay<input id="importOverlay" type="file" accept="application/json,.json" hidden></label></div></div></section>`;}
function workspaceBackup(){return {schema:'draw-steel-workspace-backup-v1',exportedAt:new Date().toISOString(),application:'Draw Steel Compendium Phase 7',data:{mode:state.mode,compact:state.compact,pinned:[...state.pinned],favorites:[...state.favorites],recent:state.recent,learningProgress:[...state.learningProgress],learningChecks:state.learningChecks,lastLesson:state.lastLesson,heroProfiles:state.heroProfiles,activeHeroId:state.activeHeroId,collections:state.collections,activeCollectionId:state.activeCollectionId,encounters:state.encounters,activeEncounterId:state.activeEncounterId,conditionDeck:[...state.conditionDeck],errataOverlays:state.errataOverlays,overlayPacks:state.overlayPacks}};}
function backupHTML(){const pending=state.pendingImport;return `<div class="data-grid"><section class="data-panel"><header class="data-panel-head"><div><h3>Workspace backup</h3><p>Back up private browser-local work separately from the compendium content.</p></div></header><div class="data-panel-body"><div class="data-stats"><div class="data-stat"><strong>${state.heroProfiles.length}</strong><span>Heroes</span></div><div class="data-stat"><strong>${state.collections.length}</strong><span>Collections</span></div><div class="data-stat"><strong>${state.encounters.length}</strong><span>Encounters</span></div><div class="data-stat"><strong>${state.errataOverlays.length}</strong><span>Annotations</span></div><div class="data-stat"><strong>${state.pinned.size}</strong><span>Pins</span></div><div class="data-stat"><strong>${state.learningProgress.size}</strong><span>Learning steps</span></div></div><div class="data-actions"><button class="data-btn primary" id="exportBackup">Download complete backup</button><button class="data-btn" id="exportPreferences">Preferences summary</button></div><div class="data-note">The backup can contain character names, campaign notes, and personal annotations. Treat it as private data.</div></div></section><aside><section class="data-panel"><header class="data-panel-head"><div><h3>Import workspace data</h3><p>Preview before merging or replacing local data.</p></div></header><div class="data-panel-body"><div class="import-drop"><input id="workspaceImportFile" type="file" accept="application/json,.json"><div class="drop-hint">Supports workspace backups plus earlier hero, collection, and encounter exports.</div></div>${pending?importPreviewHTML(pending):''}</div></section></aside></div>`;}
function importPreviewHTML(pending){return `<div class="import-report"><div class="import-report-head">${esc(pending.kind)} · ${pending.valid?'Valid':'Cannot import'}</div><div class="import-report-body">${esc(pending.message)}${pending.valid?`<div class="data-actions"><button class="data-btn primary" id="applyImportMerge">Merge</button><button class="data-btn" id="applyImportReplace" ${pending.kind==='Complete workspace backup'?'':'disabled'}>Replace workspace</button><button class="data-btn" id="cancelImport">Cancel</button></div>`:''}</div></div>`;}
function parseWorkspaceImport(payload){if(payload?.schema==='draw-steel-workspace-backup-v1'&&payload.data)return {valid:true,kind:'Complete workspace backup',message:`${(payload.data.heroProfiles||[]).length} heroes, ${(payload.data.collections||[]).length} collections, ${(payload.data.encounters||[]).length} encounters, ${(payload.data.errataOverlays||[]).length} annotations.`,payload};if(payload?.schema==='draw-steel-player-workspace-v1'&&payload.profile)return {valid:true,kind:'Hero profile',message:`Import hero “${payload.profile.name||'Untitled'}”.`,payload};if(payload?.schema==='draw-steel-session-collection-v1'&&payload.collection)return {valid:true,kind:'Session collection',message:`Import collection “${payload.collection.name||'Untitled'}”.`,payload};if(payload?.schema==='draw-steel-encounter-v1'&&payload.id)return {valid:true,kind:'Encounter',message:`Import encounter “${payload.name||'Untitled'}”.`,payload};return {valid:false,kind:'Unknown JSON',message:'No supported workspace schema was found.',payload:null};}
function mergeById(current,incoming,sanitizer){const map=new Map(current.map(item=>[item.id,item]));for(const raw of incoming||[]){const item=sanitizer(raw);if(item)map.set(item.id,item);}return [...map.values()];}
function applyPendingImport(replace=false){const pending=state.pendingImport;if(!pending?.valid)return;const p=pending.payload;if(p.schema==='draw-steel-workspace-backup-v1'){const d=p.data||{};if(replace){state.heroProfiles=(d.heroProfiles||[]).map(sanitizeHeroProfile);state.collections=(d.collections||[]).map(sanitizeCollection);state.encounters=(d.encounters||[]).map(sanitizeEncounter);state.pinned=new Set((d.pinned||[]).filter(id=>RECORD_BY_ID.has(id)));state.favorites=new Set((d.favorites||[]).filter(id=>RECORD_BY_ID.has(id)));state.recent=(d.recent||[]).filter(id=>RECORD_BY_ID.has(id));state.learningProgress=new Set(d.learningProgress||[]);state.learningChecks=d.learningChecks||{};state.errataOverlays=(d.errataOverlays||[]).map(sanitizeErrata).filter(Boolean);state.overlayPacks=(d.overlayPacks||[]).map(sanitizeOverlayPack).filter(pack=>pack.patches.length);state.conditionDeck=new Set((d.conditionDeck||[]).filter(id=>RECORD_BY_ID.get(id)?.type==='condition'));}else{state.heroProfiles=mergeById(state.heroProfiles,d.heroProfiles,sanitizeHeroProfile);state.collections=mergeById(state.collections,d.collections,sanitizeCollection);state.encounters=mergeById(state.encounters,d.encounters,sanitizeEncounter);state.pinned=new Set([...state.pinned,...(d.pinned||[]).filter(id=>RECORD_BY_ID.has(id))]);state.favorites=new Set([...state.favorites,...(d.favorites||[]).filter(id=>RECORD_BY_ID.has(id))]);state.learningProgress=new Set([...state.learningProgress,...(d.learningProgress||[])]);state.errataOverlays=mergeById(state.errataOverlays,d.errataOverlays,sanitizeErrata);state.overlayPacks=mergeById(state.overlayPacks,d.overlayPacks,sanitizeOverlayPack);} }else if(p.schema==='draw-steel-player-workspace-v1')state.heroProfiles=mergeById(state.heroProfiles,[p.profile],sanitizeHeroProfile);else if(p.schema==='draw-steel-session-collection-v1')state.collections=mergeById(state.collections,[p.collection],sanitizeCollection);else if(p.schema==='draw-steel-encounter-v1')state.encounters=mergeById(state.encounters,[p],sanitizeEncounter);if(!state.heroProfiles.length)state.heroProfiles=[createHeroProfile()];state.activeHeroId=state.heroProfiles[0].id;refreshOverlaySearchIndex();state.pendingImport=null;persist();renderDataTools();}
function updatesHTML(){const comparison=state.updateComparison;return `<div class="data-grid"><section class="data-panel"><header class="data-panel-head"><div><h3>Compare normalized packages</h3><p>Identify added, changed, and missing stable IDs before replacing authoritative data.</p></div></header><div class="data-panel-body"><div class="import-drop"><input id="comparePackageFile" type="file" accept="application/json,.json"><div class="drop-hint">Select a draw-steel-normalized-package-v1 file or an object containing a records array.</div></div><div class="data-note data-warning">Phase 7 performs comparison only. It does not overwrite embedded authoritative records inside this HTML file. Applying a reviewed update remains a build-time operation.</div>${comparison?comparisonHTML(comparison):''}</div></section><aside><section class="data-panel"><header class="data-panel-head"><div><h3>Current dataset</h3><p>Stable baseline for update tooling.</p></div></header><div class="data-panel-body"><div class="data-stats"><div class="data-stat"><strong>${RECORDS.length.toLocaleString()}</strong><span>Records</span></div><div class="data-stat"><strong>${DATA.report?.issueCount||0}</strong><span>Validation issues</span></div><div class="data-stat"><strong>${fnv1a(RECORDS.map(cleanSerializable))}</strong><span>Checksum</span></div></div><div class="data-actions"><button class="data-btn" id="exportBaselineManifest">Baseline manifest</button></div></div></section></aside></div>`;}
function comparePackage(payload){const incoming=Array.isArray(payload?.records)?payload.records:Array.isArray(payload?.data?.records)?payload.data.records:null;if(!incoming)return {valid:false,message:'No records array found.'};const currentMap=new Map(RECORDS.map(r=>[r.id,r])),incomingMap=new Map(incoming.filter(r=>r&&r.id).map(r=>[r.id,r]));const changes=[];for(const [id,record] of incomingMap){const current=currentMap.get(id);if(!current)changes.push({status:'added',id,name:record.name||id});else if(canonicalRecordHash(current)!==canonicalRecordHash(record))changes.push({status:'changed',id,name:record.name||current.name});}for(const [id,record] of currentMap)if(!incomingMap.has(id))changes.push({status:'missing',id,name:record.name});changes.sort((a,b)=>a.status.localeCompare(b.status)||a.name.localeCompare(b.name));return {valid:true,comparedAt:new Date().toISOString(),incomingCount:incomingMap.size,currentCount:currentMap.size,added:changes.filter(x=>x.status==='added').length,changed:changes.filter(x=>x.status==='changed').length,missing:changes.filter(x=>x.status==='missing').length,unchanged:incomingMap.size-changes.filter(x=>x.status!=='missing').length,changes};}
function comparisonHTML(c){if(!c.valid)return `<div class="import-report"><div class="import-report-body">${esc(c.message)}</div></div>`;return `<div class="data-stats" style="margin-top:10px"><div class="data-stat"><strong>${c.added}</strong><span>Added</span></div><div class="data-stat"><strong>${c.changed}</strong><span>Changed</span></div><div class="data-stat"><strong>${c.missing}</strong><span>Missing</span></div><div class="data-stat"><strong>${c.unchanged}</strong><span>Unchanged</span></div></div><div class="data-actions"><button class="data-btn" id="exportComparison">Export report</button></div><div class="comparison-list">${c.changes.slice(0,300).map(item=>`<div class="comparison-row"><span class="status ${item.status}">${item.status}</span><span>${esc(item.name)}</span><span>${esc(item.id)}</span></div>`).join('')}${c.changes.length>300?`<div class="comparison-row"><span>…</span><span>${(c.changes.length-300).toLocaleString()} additional changes in exported report</span><span></span></div>`:''}</div>`;}
function renderDataTools(){const tab=DATA_TABS.find(item=>item[0]===state.dataTab)||DATA_TABS[0];const content=state.dataTab==='exports'?exportCenterHTML():state.dataTab==='vtt'?vttHTML():state.dataTab==='errata'?errataHTML():state.dataTab==='backup'?backupHTML():updatesHTML();workspace.innerHTML=`<section class="data-shell"><div class="data-wrap"><header class="data-hero"><div class="eyebrow">Integrations and data portability</div><h2>${esc(tab[2])}</h2><p>Move information between tools while preserving stable IDs, source provenance, and the boundary between authoritative records and user-supplied overlays.</p></header><nav class="data-tabs" aria-label="Data tools">${DATA_TABS.map(item=>`<button class="data-tab ${item[0]===state.dataTab?'active':''}" data-data-tab="${item[0]}">${item[1]} ${esc(item[2])}</button>`).join('')}</nav>${content}</div></section>`;wireDataTools();}
function resolveRecordInput(value){const text=String(value||'').trim();if(RECORD_BY_ID.has(text))return RECORD_BY_ID.get(text);const exact=RECORDS.filter(r=>normalize(r.name)===normalize(text));return exact.length===1?exact[0]:null;}
function readJSONFile(file,callback){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{callback(JSON.parse(String(reader.result||'')));}catch(error){alert('The selected file is not valid JSON: '+error.message);}};reader.readAsText(file);}
function wireDataTools(){document.querySelectorAll('[data-data-tab]').forEach(button=>button.onclick=()=>openDataTools(button.dataset.dataTab));if(state.dataTab==='exports')wireExportCenter();else if(state.dataTab==='vtt')wireVtt();else if(state.dataTab==='errata')wireErrata();else if(state.dataTab==='backup')wireBackup();else wireUpdates();}
function wireExportCenter(){const change=(id,key)=>document.getElementById(id)?.addEventListener('change',e=>{state[key]=e.target.value;persist();renderDataTools();setHash(false);});change('exportSource','exportSource');change('exportFormat','exportFormat');change('exportType','exportType');change('exportCategory','exportCategory');document.getElementById('runExport')?.addEventListener('click',()=>runExport(currentExportRecords(),state.exportFormat,'draw-steel-'+state.exportSource));document.getElementById('exportManifest')?.addEventListener('click',()=>{const records=currentExportRecords();downloadObject({schema:'draw-steel-package-manifest-v1',createdAt:new Date().toISOString(),recordCount:records.length,checksum:fnv1a(records.map(cleanSerializable)),ids:records.map(r=>r.id)},'draw-steel-manifest.json');});}
function wireVtt(){document.getElementById('exportFoundry')?.addEventListener('click',()=>runExport(currentExportRecords(),'foundry','draw-steel-vtt'));document.getElementById('exportRoll20')?.addEventListener('click',()=>runExport(currentExportRecords(),'roll20','draw-steel-vtt'));document.getElementById('copyVttSample')?.addEventListener('click',async()=>{const text=document.getElementById('vttSample')?.value||'';try{await navigator.clipboard.writeText(text);document.getElementById('copyVttSample').textContent='Copied';}catch{prompt('Copy payload:',text);}});}
function wireErrata(){document.getElementById('clearErrataFilter')?.addEventListener('click',()=>{state.errataFilterRecordId='';renderDataTools();});document.getElementById('addErrata')?.addEventListener('click',()=>{const record=resolveRecordInput(document.getElementById('errataRecord').value);const text=document.getElementById('errataText').value.trim();if(!record){alert('Choose a valid stable ID or an exact unique record name.');return;}if(!text){alert('Enter annotation text.');return;}const item=sanitizeErrata({recordId:record.id,status:document.getElementById('errataStatus').value,title:document.getElementById('errataTitle').value||'Annotation',text,source:document.getElementById('errataSource').value,sourceUrl:document.getElementById('errataUrl').value,effectiveDate:document.getElementById('errataDate').value});state.errataOverlays.push(item);state.errataFilterRecordId=record.id;refreshOverlaySearchIndex();persist();renderDataTools();});document.querySelectorAll('[data-delete-errata]').forEach(button=>button.onclick=()=>{state.errataOverlays=state.errataOverlays.filter(item=>item.id!==button.dataset.deleteErrata);refreshOverlaySearchIndex();persist();renderDataTools();});document.querySelectorAll('[data-open-errata-record]').forEach(button=>button.onclick=()=>openRecord(button.dataset.openErrataRecord));document.getElementById('exportErrata')?.addEventListener('click',()=>downloadObject({schema:'draw-steel-errata-pack-v1',manifest:{name:'Compendium annotations',exportedAt:new Date().toISOString()},items:state.errataOverlays},'draw-steel-errata.json'));document.getElementById('importErrata')?.addEventListener('change',e=>readJSONFile(e.target.files[0],payload=>{const items=payload?.schema==='draw-steel-errata-pack-v1'?payload.items:Array.isArray(payload)?payload:[];state.errataOverlays=mergeById(state.errataOverlays,items,sanitizeErrata);refreshOverlaySearchIndex();persist();renderDataTools();}));document.getElementById('downloadOverlayTemplate')?.addEventListener('click',()=>downloadObject({schema:'draw-steel-overlay-pack-v1',manifest:{name:'My overlay',version:'1.0',source:'',notes:''},patches:[{recordId:'condition-prone',aliases:['knocked down'],tags:['example'],note:'Non-destructive annotation.'}]},'draw-steel-overlay-template.json'));document.getElementById('importOverlay')?.addEventListener('change',e=>readJSONFile(e.target.files[0],payload=>{if(payload?.schema!=='draw-steel-overlay-pack-v1'){alert('Not a draw-steel-overlay-pack-v1 file.');return;}const pack=sanitizeOverlayPack(payload);if(!pack.patches.length){alert('The overlay contains no patches matching current stable IDs.');return;}state.overlayPacks=mergeById(state.overlayPacks,[pack],sanitizeOverlayPack);refreshOverlaySearchIndex();persist();renderDataTools();}));document.querySelectorAll('[data-delete-overlay]').forEach(button=>button.onclick=()=>{state.overlayPacks=state.overlayPacks.filter(pack=>pack.id!==button.dataset.deleteOverlay);refreshOverlaySearchIndex();persist();renderDataTools();});}
function wireBackup(){document.getElementById('exportBackup')?.addEventListener('click',()=>downloadObject(workspaceBackup(),'draw-steel-workspace-backup.json'));document.getElementById('exportPreferences')?.addEventListener('click',()=>downloadObject({schema:'draw-steel-preferences-summary-v1',exportedAt:new Date().toISOString(),mode:state.mode,compact:state.compact,pinnedCount:state.pinned.size,favoritesCount:state.favorites.size,heroCount:state.heroProfiles.length,collectionCount:state.collections.length,encounterCount:state.encounters.length,learningCompleted:state.learningProgress.size,errataCount:state.errataOverlays.length},'draw-steel-preferences-summary.json'));document.getElementById('workspaceImportFile')?.addEventListener('change',e=>readJSONFile(e.target.files[0],payload=>{state.pendingImport=parseWorkspaceImport(payload);renderDataTools();}));document.getElementById('applyImportMerge')?.addEventListener('click',()=>applyPendingImport(false));document.getElementById('applyImportReplace')?.addEventListener('click',()=>applyPendingImport(true));document.getElementById('cancelImport')?.addEventListener('click',()=>{state.pendingImport=null;renderDataTools();});}
function wireUpdates(){document.getElementById('comparePackageFile')?.addEventListener('change',e=>readJSONFile(e.target.files[0],payload=>{state.updateComparison=comparePackage(payload);renderDataTools();}));document.getElementById('exportComparison')?.addEventListener('click',()=>downloadObject({schema:'draw-steel-update-comparison-v1',...state.updateComparison},'draw-steel-update-comparison.json'));document.getElementById('exportBaselineManifest')?.addEventListener('click',()=>downloadObject({schema:'draw-steel-baseline-manifest-v1',generatedAt:new Date().toISOString(),recordCount:RECORDS.length,datasetChecksum:fnv1a(RECORDS.map(cleanSerializable)),records:RECORDS.map(record=>({id:record.id,name:record.name,type:record.type,hash:canonicalRecordHash(record)}))},'draw-steel-baseline-manifest.json'));}
'''
status_marker = 'function renderStatus() {'
if status_marker not in html: raise SystemExit('status marker missing')
html = html.replace(status_marker, phase7_js + '\n' + status_marker, 1)

# Render dispatch and top button.
html = html.replace("  else if (state.view === 'director') renderDirectorTools();\n  else if (state.view === 'status')", "  else if (state.view === 'director') renderDirectorTools();\n  else if (state.view === 'data') renderDataTools();\n  else if (state.view === 'status')", 1)
html = html.replace("document.getElementById('directorBtn').onclick = () => openDirectorTools('monsters');", "document.getElementById('dataBtn').onclick = () => openDataTools('exports');\ndocument.getElementById('directorBtn').onclick = () => openDirectorTools('monsters');", 1)

OUT.write_text(html, encoding='utf-8')

checks = {
  'data workspace renderer': 'function renderDataTools()' in html,
  'structured export': 'function normalizedPackage(records' in html,
  'csv export': 'function recordsCSV(records)' in html,
  'markdown export': 'function recordsMarkdown(records)' in html,
  'foundry package': 'function foundryPackage(records)' in html,
  'roll20 package': 'function roll20Package(records)' in html,
  'record drag payload': 'application/x-draw-steel-record+json' in html,
  'errata overlays': 'function recordOverlayHTML(record)' in html,
  'workspace backup': "schema:'draw-steel-workspace-backup-v1'" in html,
  'overlay import': "schema:'draw-steel-overlay-pack-v1'" in html,
  'update comparison': 'function comparePackage(payload)' in html,
  'data route': "state.view === 'data'" in html,
  'data top button': 'id="dataBtn"' in html,
}
if not all(checks.values()): raise SystemExit('Static assertions failed: '+json.dumps(checks))

changelog = {
  'phase': 7,
  'name': 'Integrations and Data Portability',
  'input': SRC.name,
  'output': OUT.name,
  'features': [
    'Dedicated Data and Integrations workspace with versioned export and import schemas',
    'Bulk normalized JSON, CSV, and Markdown exports from all records, current results, pins, favorites, hero references, collections, encounters, record types, or categories',
    'Generic Foundry portable Actor and Item package with stable Draw Steel flags',
    'Generic Roll20 handout package with source provenance and stable IDs',
    'Drag-and-drop record payloads in custom JSON, standard JSON, and Markdown text formats',
    'Non-destructive errata and annotation overlays with source labels, URLs, dates, and status classifications',
    'Importable overlay packs for aliases, tags, and notes keyed to stable record IDs',
    'Complete private workspace backup and previewed merge or replacement imports',
    'Backward-compatible imports for earlier hero, collection, and encounter export schemas',
    'Normalized-package comparison identifying added, changed, missing, and unchanged stable IDs without overwriting embedded content',
    'Deterministic dataset and package checksums plus exportable baseline manifests',
    'Persistent routing and navigation for all data tools'
  ],
  'data_policy': 'Authoritative embedded records remain immutable at runtime. Imported errata, aliases, tags, and notes are stored as visibly separate local overlays. Workspace backups can contain private campaign data.',
  'static_checks': checks
}
CHANGELOG.write_text(json.dumps(changelog, indent=2), encoding='utf-8')
print(json.dumps({'output':str(OUT),'bytes':OUT.stat().st_size,'changelog':str(CHANGELOG),'checks':checks},indent=2))
